import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import { GUIDES } from '../../data/guides';
import '../../styles/marketing.css';
import T from '../../i18n/LocalizedText';
import { usePageI18n } from '../../i18n';

export default function GuidesIndex(pageContext) {
  const { locale } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Messaging guides — how orchestration works"
        description="How message orchestration actually works: bring-your-own-account, SMS segments and billing, opt-out handling, delivery receipts, pacing and failover."
        pathname="/guides/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="guides.001">Guides</T></span>
          <h1><T id="guides.002">How this actually works</T></h1>
          <p className="mk-lead"><T id="guides.003">
            The parts of messaging that are easy to get subtly wrong: what a segment is, where the
            rate limit really lives, why an accepted message is not a delivered one. Written from
            what the platform does, not from what would sound good.
          </T></p>
        </header>

        <section className="mk-section">
          <div className="mk-grid">
            {GUIDES.map((g) => (
              <article className="mk-card" key={g.slug}>
                <span className="mk-card-tag"><T id="guides.004">{g.readMinutes} min</T></span>
                <h3>{g.title}</h3>
                <p>{g.excerpt}</p>
                <Link className="mk-card-link" to={`/guides/${g.slug}/`}><T id="guides.005">
                  Read the guide &rarr;
                </T></Link>
              </article>
            ))}
          </div>
        </section>

        <div className="mk-scope">
          <T id="guides.006"><strong>Scope.</strong> These guides walk the SMS channel through from first connection to
          production. Email and WhatsApp work on the same connection model — pick a provider, link
          your own account, send from the console.
        </T></div>
      </div>
    </Layout>
  );
}
